1	package org.jsoup.select;
2	
3	import org.jsoup.Jsoup;
4	import org.jsoup.nodes.Document;
5	import org.jsoup.nodes.Element;
6	import org.junit.jupiter.api.Test;
7	
8	import static org.junit.jupiter.api.Assertions.*;
9	
10	/**
11	 Tests for the {@code An+B of S} extension to {@code :nth-child()} and {@code :nth-last-child()}: positions are
12	 computed against the filtered set of element siblings matching S.
13	 */
14	public class NthChildOfSelectorTest {
15	
16	    private Document mixedList() {
17	        // li items, some classed "hit", with a text node sprinkled in (non-element nodes must not take a position)
18	        return Jsoup.parse(
19	            "<ul id=list>" +
20	                "<li class='hit'>a</li>" +       // filtered pos 1 / last 5
21	                "<li>skip</li>" +
22	                "<li class='hit'>b</li>" +       // filtered pos 2 / last 4
23	                " text " +
24	                "<li class='hit other'>c</li>" + // filtered pos 3 / last 3
25	                "<li class='nope'>skip2</li>" +
26	                "<li class='hit'>d</li>" +       // filtered pos 4 / last 2
27	                "<li class='hit'>e</li>" +       // filtered pos 5 / last 1
28	            "</ul>" +
29	            "<ul id=other><li class='hit'>x1</li><li class='hit'>x2</li></ul>"
30	        );
31	    }
32	
33	    @Test void nthChildConstantOf() {
34	        Document doc = mixedList();
35	        assertTexts(doc.select("#list :nth-child(1 of .hit)"), "a");
36	        assertTexts(doc.select("#list :nth-child(2 of li.hit)"), "b");
37	        assertTexts(doc.select("#list :nth-child(3 of .hit)"), "c");
38	        assertTexts(doc.select("#list :nth-child(5 of .hit)"), "e");
39	        assertTrue(doc.select("#list :nth-child(6 of .hit)").isEmpty());
40	    }
41	
42	    @Test void nthLastChildConstantOf() {
43	        Document doc = mixedList();
44	        assertTexts(doc.select("#list :nth-last-child(1 of .hit)"), "e");
45	        assertTexts(doc.select("#list :nth-last-child(2 of .hit)"), "d");
46	        assertTexts(doc.select("#list :nth-last-child(5 of .hit)"), "a");
47	        assertTrue(doc.select("#list :nth-last-child(6 of .hit)").isEmpty());
48	
49	        // forward and reverse positions stay consistent: filter renumbers both ways
50	        assertTexts(doc.select("#list :nth-last-child(3 of .hit)"), "c");
51	    }
52	
53	    @Test void nthChildOddEvenLinearOf() {
54	        Document doc = mixedList();
55	        assertTexts(doc.select("#list :nth-child(odd of .hit)"), "a", "c", "e");
56	        assertTexts(doc.select("#list :nth-child(even of .hit)"), "b", "d");
57	        assertTexts(doc.select("#list :nth-child(2n+1 of .hit)"), "a", "c", "e");
58	        assertTexts(doc.select("#list :nth-child(2n of .hit)"), "b", "d");
59	        assertTexts(doc.select("#list :nth-child(3n+1 of .hit)"), "a", "d");
60	        assertTexts(doc.select("#list :nth-last-child(-n+2 of .hit)"), "d", "e");
61	        assertTexts(doc.select("#list :nth-child(-n+2 of .hit)"), "a", "b");
62	    }
63	
64	    @Test void nthChildWhitespaceAndCaseOf() {
65	        Document doc = mixedList();
66	        assertTexts(doc.select("#list :nth-child( 2n + 1 of .hit )"), "a", "c", "e");
67	        assertTexts(doc.select("#list :nth-child(2 OF .hit)"), "b");
68	        assertTexts(doc.select("#list :nth-child(odd   of   li[class~=hit])"), "a", "c", "e");
69	    }
70	
71	    @Test void negativeExpressionsDontMatchOutOfBounds() {
72	        Document doc = mixedList();
73	        // plain negative constant never matches (positions start at 1)
74	        assertTrue(doc.select("#list :nth-child(-5 of .hit)").isEmpty());
75	        assertTrue(doc.select("#list :nth-last-child(-5 of .hit)").isEmpty());
76	        // -n step never matches
77	        assertTrue(doc.select("#list :nth-child(-1n of .hit)").isEmpty());
78	    }
79	
80	    @Test void nonElementNodesDoNotTakePositions() {
81	        // the " text " node between b and c must not shift positions
82	        Document doc = Jsoup.parse(
83	            "<div><span class=x>1</span> <!-- comment --> <span class=x>2</span></div>");
84	        assertTexts(doc.select("div :nth-child(2 of .x)"), "2");
85	        assertTexts(doc.select("div :nth-last-child(1 of .x)"), "2");
86	    }
87	
88	    @Test void selectorListInOfCommasScopedToPseudo() {
89	        Document doc = Jsoup.parse(
90	            "<ul>" +
91	                "<li class=a>1</li>" +
92	                "<li class=b>2</li>" +
93	                "<li class=c>3</li>" +
94	                "<li class=a>4</li>" +
95	            "</ul>");
96	        // comma in of S is part of the pseudo argument, not a top-level selector separator
97	        // filtered set is li1(a)=1, li2(b)=2, li4(a)=3
98	        assertTexts(doc.select("ul :nth-child(2 of .a, .b)"), "2");
99	        assertTexts(doc.select("ul :nth-last-child(1 of .a, .b)"), "4");
100	    }
101	
102	    @Test void commasInAttributeValuesDoNotEndOfClause() {
103	        Document doc = Jsoup.parse(
104	            "<ul>" +
105	                "<li data-x='1,2'>a1</li>" +
106	                "<li data-x='z'>skip</li>" +
107	                "<li data-x='1,2'>a2</li>" +
108	            "</ul>");
109	        assertTexts(doc.select("ul :nth-child(2 of li[data-x='1,2'])"), "a2");
110	        // commas inside a nested pseudo's own selector list must not end the of argument either
111	        assertTexts(doc.select("ul :nth-child(2 of li:is([data-x=z], [data-x='1,2']))"), "skip");
112	    }
113	
114	    @Test void nestedPseudoAndNotInOf() {
115	        Document doc = Jsoup.parse(
116	            "<ul>" +
117	                "<li><p>x</p></li>" +                 // 1 of :has(p)
118	                "<li class=skip>skip</li>" +
119	                "<li><p>y</p></li>" +                 // 2 of :has(p)
120	                "<li><p>z</p><em>m</em></li>" +       // 3 of :has(p) and not :has(em)
121	            "</ul>");
122	        assertTexts(doc.select("ul :nth-child(2 of li:has(p))"), "y");
123	        // nested :not with its own selector list — inner commas and parens must not end the of arg
124	        assertTexts(doc.select("ul :nth-child(2 of li:has(p):not(:has(em), .skip))"), "y");
125	        // comma after the nested pseudo still delimits the of selector list
126	        // S matches li2 (.skip, pos 1) and li4 (:has(em), pos 2) — pos 1 selects only li2
127	        Elements crossList = doc.select("ul :nth-child(1 of li:has(em), li.skip)");
128	        assertEquals(1, crossList.size());
129	        assertEquals("skip", crossList.get(0).text());
130	    }
131	
132	    @Test void combinatorsAllowedInOf() {
133	        Document doc = Jsoup.parse(
134	            "<section>" +
135	                "<div><em class=t>1</em><span>x</span><em class=t>2</em></div>" +
136	            "</section>");
137	        assertTexts(doc.select("section :nth-child(2 of div > em.t)"), "2");
138	        assertTexts(doc.select("section :nth-last-child(1 of div > em)"), "2");
139	    }
140	
141	    @Test void outerSelectorIntersectsWithOfPosition() {
142	        Document doc = Jsoup.parse(
143	            "<ul>" +
144	                "<li class='a hit'>1</li>" +
145	                "<li class='b hit'>2</li>" +
146	                "<li class='a hit'>3</li>" +
147	            "</ul>");
148	        // among .hit the positions are 1,2,3; outer .a intersects
149	        assertTexts(doc.select("ul li.a:nth-child(2 of .hit)")); // pos 2 is class b
150	        assertTexts(doc.select("ul li.a:nth-child(3 of .hit)"), "3");
151	    }
152	
153	    @Test void combinesWithChildAdjacentAndNot() {
154	        Document doc = Jsoup.parse(
155	            "<ol>" +
156	                "<li class=h>1</li>" +
157	                "<li class=h>2</li>" +
158	                "<li class=h>3</li>" +
159	            "</ol>");
160	        assertTexts(doc.select("ol > :nth-child(2 of .h)"), "2");
161	        assertTexts(doc.select("ol .h + .h:nth-child(3 of .h)"), "3"); // adjacent and nth
162	        assertTexts(doc.select("ol :nth-child(2 of .h):not(:first-child)"), "2");
163	    }
164	
165	    @Test void eachParentCountedIndependently() {
166	        Document doc = Jsoup.parse(
167	            "<div id=a><span class=x>a1</span><span class=x>a2</span></div>" +
168	            "<div id=b><span class=x>b1</span><span class=x>b2</span><span class=x>b3</span></div>");
169	        assertTexts(doc.select("body :nth-child(1 of .x)"), "a1", "b1");
170	        assertTexts(doc.select("body :nth-last-child(1 of .x)"), "a2", "b3");
171	    }
172	
173	    @Test void descendantsAndRootScopeNotCounted() {
174	        Document doc = Jsoup.parse(
175	            "<div id=root><span class=x>root1<span class=x>inner</span></span><span class=x>root2</span></div>");
176	        Elements els = doc.select("#root > :nth-child(2 of .x)");
177	        assertTexts(els, "root2"); // only the direct child spans are siblings; inner is under root1
178	    }
179	
180	    @Test void noMatchesGivesDeterministicEmptyResult() {
181	        Document doc = mixedList();
182	        assertTrue(doc.select("#list :nth-child(1 of .does-not-exist)").isEmpty());
183	        assertTrue(doc.select("#list :nth-last-child(2 of .does-not-exist)").isEmpty());
184	    }
185	
186	    @Test void documentOrderAndNoDuplicates() {
187	        Document doc = Jsoup.parse(
188	            "<ul>" +
189	                "<li class='a b'>1</li>" +
190	                "<li class='a'>2</li>" +
191	                "<li class='b'>3</li>" +
192	            "</ul>");
193	        // first list item matches both branches of the of selector list — must be returned once, in doc order
194	        Elements els = doc.select("ul :nth-child(odd of .a, .b)");
195	        assertEquals(2, els.size());
196	        assertEquals("1", els.get(0).text());
197	        assertEquals("3", els.get(1).text());
198	    }
199	
200	    @Test void domMutationsReflectedImmediately() {
201	        Document doc = mixedList();
202	        Evaluator eval = Selector.evaluatorOf("#list :nth-child(2 of .hit)");
203	        assertTexts(doc.select(eval), "b");
204	
205	        // remove an earlier matching sibling: filtered positions renumber
206	        doc.select("#list .hit").first().remove(); // removes a; hits now b,c,d,e
207	        assertTexts(doc.select(eval), "c");
208	
209	        // change the attribute used by S: c drops out of the set, d becomes position 2
210	        doc.select("#list .hit").get(1).removeAttr("class"); // b idx0, c idx1
211	        assertTexts(doc.select(eval), "d");
212	
213	        // insert a fresh matching sibling at the front: it takes position 1
214	        Element list = doc.expectFirst("#list");
215	        list.prependChild(new Element("li").addClass("hit").text("z"));
216	        assertTexts(doc.select(eval), "b");
217	
218	        // the reverse query is recomputed the same way against the live DOM
219	        Evaluator lastEval = Selector.evaluatorOf("#list :nth-last-child(1 of .hit)");
220	        assertTexts(doc.select(lastEval), "e");
221	    }
222	
223	    @Test void plainNthChildBehaviorUnchanged() {
224	        Document doc = Jsoup.parse("<div><p>1</p><p>2</p><p>3</p></div>");
225	        assertTexts(doc.select("div :nth-child(2)"), "2");
226	        assertTexts(doc.select("div :nth-last-child(2)"), "2");
227	        assertTexts(doc.select("div :nth-child(odd)"), "1", "3");
228	    }
229	
230	    @Test void parseErrorsDoNotReturnPartialResultsOrMutateDom() {
231	        Document doc = mixedList();
232	        String html = doc.html();
233	
234	        assertParseError(":nth-child(of .hit)");            // missing formula
235	        assertParseError(":nth-child(1 of)");               // missing selector
236	        assertParseError(":nth-child(1 of ");               // missing closing paren
237	        assertParseError(":nth-child(1 of .hit");           // unbalanced
238	        assertParseError(":nth-child(bogus of .hit)");      // invalid formula
239	        assertParseError(":nth-of-type(1 of .hit)");        // of not valid for nth-of-type
240	        assertParseError(":nth-last-of-type(1 of .hit)");
241	
242	        // DOM untouched
243	        assertEquals(html, doc.html());
244	
245	        // and the next valid query works against the full current DOM
246	        assertTexts(doc.select("#list :nth-child(2 of .hit)"), "b");
247	    }
248	
249	    @Test void parsedEvaluatorToString() {
250	        assertEquals(":nth-child(2n+1 of .hit)", Selector.evaluatorOf(":nth-child(odd of .hit)").toString());
251	        assertEquals(":nth-last-child(2 of li.x)", Selector.evaluatorOf(":nth-last-child(2 of li.x)").toString());
252	    }
253	
254	    private void assertParseError(String css) {
255	        assertThrows(Selector.SelectorParseException.class, () -> Selector.evaluatorOf(css),
256	            () -> "Expected parse error for: " + css);
257	    }
258	
259	    private static void assertTexts(Elements els, String... texts) {
260	        assertEquals(texts.length, els.size(),
261	            () -> "Expected " + texts.length + " elements but got " + els.size() + ": " + els.outerHtml());
262	        for (int i = 0; i < texts.length; i++) {
263	            String expected = texts[i];
264	            String actual = expected.startsWith("<") ? els.get(i).outerHtml() : els.get(i).text();
265	            assertEquals(expected, actual, "Element " + i);
266	        }
267	    }
268	}
