266	    // ::comment etc
267	    private Evaluator parseNodeSelector() {
268	        final String pseudo = tq.consumeCssIdentifier();
269	        inNodeContext = true;  // Enter node context
270	
271	        Evaluator left;
272	        switch (pseudo) {
273	            case "node":
274	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
275	                break;
276	            case "leafnode":
277	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
278	                break;
279	            case "text":
280	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
281	                break;
282	            case "comment":
283	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
284	                break;
285	            case "data":
286	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
287	                break;
288	            case "cdata":
289	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
290	                break;
