296	        // Handle following subclasses in node context (like ::comment:contains())
297	        Evaluator right;
298	        while ((right = parseSubclass()) != null) {
299	            left = and(left, right);
300	        }
301	
302	        inNodeContext = false;
303	        return left;
304	    }
