306	    private Evaluator byId() {
307	        String id = tq.consumeCssIdentifier();
308	        Validate.notEmpty(id);
309	        return new Evaluator.Id(id);
310	    }
311	
312	    private Evaluator byClass() {
313	        String className = tq.consumeCssIdentifier();
314	        Validate.notEmpty(className);
315	        return new Evaluator.Class(className.trim());
316	    }
317	
318	    private Evaluator byTag() {
319	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
320	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
321	        // consistency - both the selector and the element tag
322	        String tagName = normalize(tq.consumeElementSelector());
323	        Validate.notEmpty(tagName);
324	
325	        // namespaces:
326	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
327	            String plainTag = tagName.substring(2); // strip *|
328	            return new CombiningEvaluator.Or(
329	                new Evaluator.Tag(plainTag),
330	                new Evaluator.TagEndsWith(":" + plainTag)
331	            );
332	        } else if (tagName.endsWith("|*")) { // ns|*
333	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
334	            return new Evaluator.TagStartsWith(ns);
335	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
336	            tagName = tagName.replace("|", ":");
337	        }
338	
339	        return new Evaluator.Tag(tagName);
340	    }
341	
342	    private Evaluator byAttribute() {
343	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
344	            return evaluatorForAttribute(cq);
345	        }
346	    }
347	
348	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
349	        String key = cq.consumeToAny(AttributeEvals); // eq, not, start, end, contain, match, (no val)
350	        key = normalize(key);
351	        Validate.notEmpty(key);
352	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
353	        cq.consumeWhitespace();
354	        final Evaluator eval;
355	
356	        if (cq.isEmpty()) {
357	            if (key.startsWith("^"))
358	                eval = new Evaluator.AttributeStarting(key.substring(1));
359	            else if (key.equals("*")) // any attribute
360	                eval = new Evaluator.AttributeStarting("");
361	            else
362	                eval = new Evaluator.Attribute(key);
363	        } else {
364	            if (cq.matchChomp('='))
365	                eval = new Evaluator.AttributeWithValue(key, cq.remainder());
366	            else if (cq.matchChomp("!="))
367	                eval = new Evaluator.AttributeWithValueNot(key, cq.remainder());
368	            else if (cq.matchChomp("^="))
369	                eval = new Evaluator.AttributeWithValueStarting(key, cq.remainder());
370	            else if (cq.matchChomp("$="))
371	                eval = new Evaluator.AttributeWithValueEnding(key, cq.remainder());
372	            else if (cq.matchChomp("*="))
373	                eval = new Evaluator.AttributeWithValueContaining(key, cq.remainder());
374	            else if (cq.matchChomp("~="))
375	                eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder()));
376	            else
377	                throw new Selector.SelectorParseException(
378	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
379	        }
380	        return eval;
381	    }
