383	    //pseudo selectors :first-child, :last-child, :nth-child, ...
384	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
385	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
386	
387	    private Evaluator cssNthChild(boolean last, boolean ofType) {
388	        String arg = consumeParens(); // arg is like "odd", "-n+2", or "2n+1 of .foo .bar"
389	        int ofIdx = indexOfOfClause(arg);
390	        final String formula = normalize(ofIdx < 0 ? arg : arg.substring(0, ofIdx)).replaceAll("\\s+", "");
391	        final int step, offset;
392	        if ("odd".equals(formula)) {
393	            step = 2;
394	            offset = 1;
395	        } else if ("even".equals(formula)) {
396	            step = 2;
397	            offset = 0;
398	        } else {
399	            Matcher stepOffsetM, stepM;
400	            if ((stepOffsetM = NthStepOffset.matcher(formula)).matches()) {
401	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
402	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
403	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
404	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
405	                offset =
406	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
407	            } else if ((stepM = NthOffset.matcher(formula)).matches()) {
408	                step = 0;
409	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
410	            } else {
411	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", formula);
412	            }
413	        }
414	
415	        Evaluator ofSelector = null;
416	        if (ofIdx >= 0) {
417	            if (ofType)
418	                throw new Selector.SelectorParseException(
419	                    "Could not parse query '%s': 'of S' is only supported by :nth-child() and :nth-last-child()", query);
420	            String ofCss = arg.substring(ofIdx + 2).trim(); // skip "of"
421	            if (ofCss.isEmpty())
422	                throw new Selector.SelectorParseException(
423	                    "Could not parse query '%s': :nth-child(An+B of S) requires a selector", query);
424	            ofSelector = parse(ofCss); // full grammar: selector lists, combinators, attributes, nested pseudos
425	        }
426	
427	        if (ofSelector != null)
428	            return last
429	                ? new Evaluator.IsNthLastChildOfSelector(step, offset, ofSelector)
430	                : new Evaluator.IsNthChildOfSelector(step, offset, ofSelector);
431	
432	        return ofType
433	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
434	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
435	    }
