import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Probe {
    static String texts(Elements es) {
        StringBuilder sb = new StringBuilder();
        es.forEach(e -> sb.append(e.text()).append(','));
        return sb.toString();
    }
    static void check(Document doc, String css, String expect) {
        String got;
        try { got = texts(doc.select(css)); }
        catch (Exception e) { got = "ERR:" + e.getClass().getSimpleName() + ":" + e.getMessage(); }
        System.out.println((got.equals(expect) ? "OK  " : "FAIL") + " " + css + " => [" + got + "] expect [" + expect + "]");
    }
    static void checkErr(String css) {
        try { Selector.evaluatorOf(css); System.out.println("FAIL " + css + " parsed OK"); }
        catch (Selector.SelectorParseException e) { System.out.println("OK   " + css + " => parse error"); }
    }
    public static void main(String[] a) {
        Document doc = Jsoup.parse(
            "<ul id=l><li class=h>a</li><li>x</li><li class=h>b</li><li class=h>c</li></ul>" +
            "<div id=r><section><em class=t>1</em><em class=t>2</em></section></div>" +
            "<em class=t>outside</em>");

        check(doc, "#l :nth-child(n of .h)", "a,b,c,");
        check(doc, "#l :nth-child(0n+2 of .h)", "b,");
        check(doc, "#l :nth-child(+2n+1 of .h)", "a,c,");
        check(doc, "#l :nth-last-child(n of .h)", "a,b,c,");
        check(doc, "#l :nth-child( 3 )", ""); // old behavior unaffected: 3rd element child is "c"? actually li3=b
        check(doc, "#l :nth-child(3)", "b,");
        // descendant combinator inside S, scoped by query root #r: outside em must not be counted
        check(doc, "#r :nth-child(2 of section em.t)", "2,");
        // of S whose ancestor chain could leave the candidate's parent — still siblings only
        check(doc, "#r :nth-last-child(1 of section em)", "2,");
        // general sibling combinator in S
        Document d2 = Jsoup.parse("<div><i class=k>1</i><b>x</b><i class=k>2</i><i class=k>3</i></div>");
        check(d2, "div :nth-child(2 of .k ~ i)", "3,");
        // duplicate across list items returned once in doc order
        Document d3 = Jsoup.parse("<ul><li class='a b'>1</li><li class=a>2</li><li class=b>3</li></ul>");
        check(d3, "ul :nth-child(odd of .a, .b)", "1,3,");
        // toString forms
        System.out.println(Selector.evaluatorOf(":nth-child(n of .x)"));
        System.out.println(Selector.evaluatorOf(":nth-child(2n of .x)"));
        System.out.println(Selector.evaluatorOf(":nth-last-child(2n-3 of .x)"));
        // errors
        checkErr(":nth-child()");
        checkErr(":nth-child(1 of )");
        checkErr(":nth-child(1 of [attr=)");
        checkErr(":nth-child(1n of)");
        // after error, valid query on same DOM
        check(doc, "#l :nth-child(2 of .h)", "b,");
    }
}
EOF
